"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Airy docs Switch: a 2.25rem by 1.25rem track. Off, the track is a pale
 * grey well; on, it fills with the same flat green as the primary button,
 * and the white knob slides across.
 */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "group/switch peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full border border-transparent bg-(--line-strong) p-0.5",
        "transition-colors duration-fast ease-out",
        "hover:data-[unchecked]:bg-(--control)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:bg-muted",
        controlChecked,
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-4 rounded-full bg-(--thumb) shadow-(--shadow-thumb)",
          "data-[checked]:translate-x-4 data-[unchecked]:translate-x-0",
          "origin-left data-[checked]:origin-right rtl:origin-right rtl:data-[checked]:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
